    g_api.AddCallbackHook = Api_AddCallbackHook;
    g_api.NetRegister = Api_NetRegister;
    g_api.NetOn = Api_NetOn;
    g_api.NetSend = Api_NetSend;
    g_api.NetGetStatus = Api_NetGetStatus;
