    g_api.ContentAdd = Content_Add;
    g_api.ContentEdit = Content_Edit;
    g_api.ContentAddIcon = Content_AddIcon;
    g_api.AudioAdd = Audio_Add;
    g_api.MenuAddPage = Menu_AddPage;
    g_api.MenuAddOption = Menu_AddOption;
